PRINT N'';
PRINT N'======================================================';
PRINT N'  تم إنشاء قاعدة البيانات وجداولها وإدراج البيانات بنجاح  ';
PRINT N'======================================================';
SELECT 
    t.name AS [اسم الجدول],
    p.rows AS [عدد السجلات]
FROM sys.tables t
INNER JOIN sys.partitions p ON t.object_id = p.object_id
WHERE p.index_id IN (0,1)
ORDER BY p.rows DESC, t.name ASC;
GO